/** WAVs in public/sounds/ (generated by tools/gen-sounds.mjs) */
export type Clip = 'chime' | 'alarm_warning' | 'alarm_siren'

const CLIPS: Clip[] = ['chime', 'alarm_warning', 'alarm_siren']
const cache = new Map<Clip, HTMLAudioElement>()

function clip(name: Clip): HTMLAudioElement {
  let audio = cache.get(name)
  if (!audio) {
    audio = new Audio(`/sounds/${name}.wav`)
    audio.preload = 'auto'
    cache.set(name, audio)
  }
  return audio
}

// play() rejects until the page has had a user gesture; the "Enable sound" button covers that
const play = (audio: HTMLAudioElement) => void audio.play().catch(() => {})

/** Clips currently doing a muted unlock play (see unlockAudio) */
const unlocking = new Set<HTMLAudioElement>()

/** A real play takes over a pending unlock, so the unlock won't pause it */
const claim = (audio: HTMLAudioElement) => {
  unlocking.delete(audio)
  audio.muted = false
}

/** One-shot. A clip that is still playing is left alone, never restarted */
export function playOnce(name: Clip) {
  const audio = clip(name)
  if (!audio.paused && !unlocking.has(audio)) return
  claim(audio)
  audio.loop = false
  audio.currentTime = 0
  play(audio)
}

export function startLoop(name: Clip) {
  const audio = clip(name)
  claim(audio)
  audio.loop = true
  if (audio.paused) play(audio)
}

export function stopClip(name: Clip) {
  const audio = cache.get(name)
  if (!audio) return
  audio.pause()
  audio.loop = false
  audio.currentTime = 0
}

export const stopAll = () => CLIPS.forEach(stopClip)

/** Call from a click/key handler: a muted play() per clip preloads them and unlocks strict browsers (Safari) */
export function unlockAudio() {
  for (const name of CLIPS) {
    const audio = clip(name)
    if (!audio.paused) continue
    unlocking.add(audio)
    audio.muted = true
    audio
      .play()
      .then(() => {
        if (!unlocking.has(audio)) return
        audio.pause()
        audio.currentTime = 0
      })
      .catch(() => {})
      .finally(() => {
        if (unlocking.delete(audio)) audio.muted = false
      })
  }
}

const SOUND_KEY = 'car-screen:sound'

/** Remembered "Enable sound" choice. Storage can throw (private mode, blocked site data), so every access is guarded */
export function readSoundPref(): boolean {
  try {
    return localStorage.getItem(SOUND_KEY) === 'on'
  } catch {
    return false
  }
}

export function writeSoundPref(on: boolean) {
  try {
    localStorage.setItem(SOUND_KEY, on ? 'on' : 'off')
  } catch {
    // not persisted; the in-memory choice still applies
  }
}
